package com.sunrise.dentalclinic.dto;
import com.sunrise.dentalclinic.model.*;import java.math.BigDecimal;import java.time.*;
public record BillingPreview(Long appointmentId,String appointmentNumber,String patientName,String dentistName,String treatmentName,LocalDate appointmentDate,LocalTime appointmentTime,BigDecimal treatmentCost,BigDecimal consultationFee,BigDecimal totalAmount,AppointmentStatus status,Long existingBillId){public static BillingPreview from(Appointment a,BigDecimal fee,BigDecimal total,Bill bill){return new BillingPreview(a.getId(),a.getAppointmentNumber(),a.getPatient().getName(),a.getDentist().getName(),a.getTreatment().getTreatmentName(),a.getAppointmentDate(),a.getAppointmentTime(),a.getTreatment().getTreatmentCost(),fee,total,a.getStatus(),bill==null?null:bill.getId());}public boolean billable(){return status!=AppointmentStatus.CANCELLED&&existingBillId==null;}public boolean alreadyBilled(){return existingBillId!=null;}}
